  // SQL query to calculate daily traffic metrics
  const auto sql = R"(
    SELECT strftime('%Y-%m-%d', visit_time) as visit_date, 
           COUNT(*) as total_visits, 
           COUNT(DISTINCT url) as unique_pages
    FROM PageVisit
    GROUP BY visit_date
    ORDER BY visit_date
  )";

