  auto popular_users_query = R"(
    SELECT u.username, 'popular' as user2_name
    FROM User u
    LEFT JOIN Friendship f ON u.user_id = f.user_id1
    GROUP BY u.user_id, u.username
    HAVING COUNT(f.user_id2) > (
      SELECT AVG(friend_count) 
      FROM (SELECT COUNT(*) as friend_count FROM Friendship GROUP BY user_id1)
    )
    ORDER BY COUNT(f.user_id2) DESC
  )";

  auto popular_stmt = db.prepare(popular_users_query);
  while (popular_stmt.step()) {
    FriendConnection conn;
    conn.user1_name = popular_stmt.column<std::string>(0);
    conn.user2_name = "popular_user";
    results.push_back(conn);
  }

  // Query 3: Find friend-of-friend relationships (exactly one mutual friend)
  auto fof_query = R"(
    SELECT DISTINCT u1.username as user1_name, u3.username as user2_name
    FROM User u1
    INNER JOIN Friendship f1 ON u1.user_id = f1.user_id1
    INNER JOIN Friendship f2 ON f1.user_id2 = f2.user_id1
    INNER JOIN User u3 ON f2.user_id2 = u3.user_id
    WHERE u1.user_id < u3.user_id
      AND NOT EXISTS (
        SELECT 1 FROM Friendship f3 
        WHERE f3.user_id1 = u1.user_id AND f3.user_id2 = u3.user_id
      )
  )";

  auto fof_stmt = db.prepare(fof_query);
  while (fof_stmt.step()) {
    FriendConnection conn;
    conn.user1_name = fof_stmt.column<std::string>(0);
    conn.user2_name = fof_stmt.column<std::string>(1);
    results.push_back(conn);
  }

  // Query 4: Most connected users (top users by friend count)
  auto top_users_query = R"(
    SELECT u.username, 'highly_connected' as user2_name
    FROM User u
    LEFT JOIN Friendship f ON u.user_id = f.user_id1
    GROUP BY u.user_id, u.username
    ORDER BY COUNT(f.user_id2) DESC
    LIMIT 5
  )";

  auto top_stmt = db.prepare(top_users_query);
  while (top_stmt.step()) {
    FriendConnection conn;
    conn.user1_name = top_stmt.column<std::string>(0);
    conn.user2_name = "top_connected";
    results.push_back(conn);
  }

  // Query 5: Find users in same city who are not friends (recommendations)
  auto recommendations_query = R"(
    SELECT u1.username as user1_name, u2.username as user2_name
    FROM User u1
    INNER JOIN User u2 ON u1.city = u2.city
    WHERE u1.user_id < u2.user_id
      AND u1.city IS NOT NULL
      AND u1.city != ''
      AND NOT EXISTS (
        SELECT 1 FROM Friendship f 
        WHERE f.user_id1 = u1.user_id AND f.user_id2 = u2.user_id
      )
  )";

  auto rec_stmt = db.prepare(recommendations_query);
  while (rec_stmt.step()) {
    FriendConnection conn;
    conn.user1_name = rec_stmt.column<std::string>(0);
    conn.user2_name = rec_stmt.column<std::string>(1);
    results.push_back(conn);
  }

  return results;
}

