namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  sqlgen::sqlite::Database db("test_db.sqlite");

  // Prepare the SQL query to join Product and Sales tables
  // Calculate total sales amount and order by sales descending
  auto query = db.prepare(R"(
    SELECT 
      p.product_id,
      p.product_name,
      p.category,
      SUM(p.price * s.quantity) as total_sales
    FROM Product p
    INNER JOIN Sales s ON p.product_id = s.product_id
    GROUP BY p.product_id, p.product_name, p.category
    ORDER BY total_sales DESC
    LIMIT ?
  )");

  // Bind the limit parameter (top N products)
  query.bind(1, limit_count);

  // Execute query and collect results
  std::vector<TopProduct> results;
  while (query.step()) {
    TopProduct product;
    product.product_id = query.column<int>(0);
    product.product_name = query.column<std::string>(1);
    product.category = query.column<std::string>(2);
    product.total_sales = query.column<double>(3);
    results.push_back(product);
  }

  return results;
}

}  // namespace get_top_products
